import { join } from "node:path";

export const installedDir = (into: string, id: string) => {
  return { id, directory: join(into, "node_modules", "@neralabs", `rerail-pack-${id}`) };
};

export const ids = (dependencies: Record<string, unknown>) =>
  Object.entries(dependencies).flatMap(([name, spec]) => {
    if (!name.startsWith("@neralabs/rerail-pack-") || typeof spec !== "string") return [];
    const id = name.slice("@neralabs/rerail-pack-".length);
    return [{ id, spec }];
  });

import { readdirSync } from "node:fs";

export const packFolders = (scope: string) => readdirSync(scope)
    .filter(name => name.startsWith('rerail-pack-'));

