import { packIdOfPackage, rulePackPackageName } from "../engine/catalog/rule-packs.js";
import { join } from "node:path";

export const dirOf = (prefix: string, id: string) => join(prefix, "node_modules", rulePackPackageName(id));
export const idOf = (name: string) => packIdOfPackage(name);

/** Installs `@neralabs/rerail-pack-<id>` packages; see rerail-pack- naming. */
export const fail = (argument: string) => {
  throw new Error(`${argument} is not a rule pack id, a @neralabs/rerail-pack-<id> package, or a folder that exists`);
};
